let conflict=false;
class Statement{constructor(q,p=[]){if(/\b(LIKE|GLOB)\b/i.test(q)&&p.some(v=>typeof v==='string'&&v.length>50))throw Error('D1_ERROR: LIKE or GLOB pattern too complex: SQLITE_ERROR');this.q=q;this.p=p}bind(...p){return new Statement(this.q,p)}async all(){return {results:sqlite.prepare(this.q).all(...this.p),success:true,meta:{}}}async raw(){return sqlite.prepare(this.q).all(...this.p).map(x=>Object.values(x))}async run(){const r=sqlite.prepare(this.q).run(...this.p);return {results:[],success:true,meta:{changes:Number(r.changes)}}}}
globalThis.__d1={prepare:q=>new Statement(q),batch:async queries=>{if(conflict){conflict=false;sqlite.exec('UPDATE classes SET revision=revision+1')}sqlite.exec('BEGIN');try{const out=[];for(const q of queries){out.push(await q.all())}sqlite.exec('COMMIT');return out}catch(e){sqlite.exec('ROLLBACK');throw e}}};
